from google.cloud import tasks_v2
from google.protobuf import duration_pb2
import json

client = tasks_v2.CloudTasksClient()
parent = client.queue_path('my-project', 'us-central1', 'email-queue')

task = {
    'http_request': {
        'http_method': tasks_v2.HttpMethod.POST,
        'url': 'https://my-service-xyz.run.app/send-email',
        'headers': {'Content-Type': 'application/json'},
        'body': json.dumps({'order_id': '12345'}).encode(),
        'oidc_token': {
            'service_account_email': 'tasks-sa@my-project.iam.gserviceaccount.com'
        }
    }
}
client.create_task(parent=parent, task=task)
